package com.meterflow.payments;import com.meterflow.invoicing.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.scheduling.annotation.Scheduled;import java.time.*;import java.util.*;
@Service public class DunningService{private final DunningRepository cases;private final InvoiceRepository invoices;private final com.meterflow.notifications.WebhookDeliveryService webhooks;public DunningService(DunningRepository c,InvoiceRepository i,com.meterflow.notifications.WebhookDeliveryService w){cases=c;invoices=i;webhooks=w;}
@Transactional public DunningCase recordFailure(UUID invoiceId){var inv=invoices.findById(invoiceId).orElseThrow();if(!"FINALISED".equals(inv.getStatus()))throw new IllegalStateException("Only finalised invoices can enter dunning");return cases.findByInvoiceId(invoiceId).orElseGet(()->cases.save(new DunningCase(invoiceId,inv.getCustomerId())));}
@Transactional public DunningCase recordSuccess(UUID invoiceId){var c=cases.findByInvoiceId(invoiceId).orElseThrow(()->new IllegalArgumentException("No dunning case for invoice"));c.paid();return cases.save(c);}
@Transactional @Scheduled(cron="0 0 2 * * *") public void processDueRetries(){for(var c:java.util.stream.Stream.concat(cases.findByStatus("RETRYING").stream(),cases.findByStatus("PAST_DUE").stream()).toList()){if(c.getNextAttemptAt()!=null&&!c.getNextAttemptAt().isAfter(Instant.now())){c.failed();cases.save(c);webhooks.publish(c.getCustomerId(),"dunning.retry",Map.of("invoiceId",c.getInvoiceId().toString(),"attempt",c.getAttempt(),"status",c.getStatus(),"nextAttemptAt",c.getNextAttemptAt()==null?"none":c.getNextAttemptAt().toString()));}}}
public void recordSuccessIfPresent(UUID invoiceId){cases.findByInvoiceId(invoiceId).ifPresent(c->{c.paid();cases.save(c);});}public List<DunningCase> all(){return cases.findAll();}}
